  $methjson${"slug": "media-ethics", "title": "Media Ethics", "description": "A journalism ethics course on ethical frameworks and newsroom decision-making, accuracy and truth-telling, independence and conflicts of interest, minimizing harm, sourcing and anonymity, privacy and consent, deception and hidden methods, objectivity and fairness, diversity in coverage, platform and AI ethics, and accountability, corrections, and audience trust.", "topics": [{"id": "c92f1cf0-a277-4310-8692-dd01eec3f481", "type": "topic", "title": "Ethical Frameworks and Newsroom Decision-Making", "description": "Introduces professional codes, moral reasoning, stakeholder analysis, and repeatable decision tools for journalism.", "children": [{"id": "bf804efb-ec35-47b7-a674-10696974c734", "type": "subtopic", "title": "Professional ethics codes", "children": [{"id": "5723d220-5882-48ae-ab97-aad8b0d6ff6a", "type": "concept", "title": "SPJ Code"}, {"id": "6e34a34b-60eb-4792-99b5-39f88f3d218b", "type": "concept", "title": "Reuters standards"}, {"id": "9898667e-62e8-4635-9694-215e7e29b4dd", "type": "concept", "title": "NPR handbook"}, {"id": "6f7b47b5-60c9-4ce5-ab69-1683f1e82e1d", "type": "concept", "title": "Newsroom policy comparison"}], "description": "Codes give journalists shared principles, but students must learn to apply them to messy situations."}, {"id": "4de140ad-d283-4eba-a4ca-e6a3e8bf9530", "type": "subtopic", "title": "Ethical reasoning models", "children": [{"id": "05f9bc89-135b-498e-9e4a-2ad8b33a3ba4", "type": "concept", "title": "Consequences"}, {"id": "84fcc29f-7db5-447c-bf32-bcc5b28a17bf", "type": "concept", "title": "Duties"}, {"id": "629b9e7c-6ea0-45d7-a8c1-ef27ac1f3fa1", "type": "concept", "title": "Virtues"}, {"id": "7d658b24-02c5-400e-a9e3-e018c615140d", "type": "concept", "title": "Stakeholder mapping"}], "description": "Decision frameworks slow down reactive judgment and make tradeoffs visible."}, {"id": "57ac3cb5-1e3d-4bc7-9e12-1a7f3cb0bb3b", "type": "subtopic", "title"