oration"}, {"id": "d7a080e2-e521-49e0-b636-c33cf095c36b", "type": "concept", "title": "Editor approval"}], "description": "Anonymity can protect vulnerable sources or enable manipulation, so it requires strict tests."}, {"id": "2cd0d4a1-e6b6-4db8-9e21-042854eb4331", "type": "subtopic", "title": "Source capture", "children": [{"id": "846b16f4-66d6-4dae-a9a7-8582faaa9b5b", "type": "concept", "title": "Access journalism"}, {"id": "ef6752a5-c507-4153-93ba-1c40dc944abd", "type": "concept", "title": "Overfamiliarity"}, {"id": "bf5f402e-1f30-4e22-9f54-b5a8ee4fcc36", "type": "concept", "title": "Source diversity"}, {"id": "264e905a-198c-4e37-9986-ff6507b0f453", "type": "concept", "title": "Rotating perspectives"}], "description": "Beat relationships can create dependency and narrowed judgment."}]}, {"id": "d4fec7e8-20b6-4bbb-aee6-2e23d4206ad6", "type": "topic", "title": "Privacy, Public Interest, and Consent", "description": "Develops judgment about private information, public relevance, consent, exposure, and digital permanence.", "children": [{"id": "16bba6e7-e8b1-4b71-a038-c61af83d3d9f", "type": "subtopic", "title": "Public interest tests", "children": [{"id": "69485b6a-dd84-4d95-9f0a-1a7cabce9b19", "type": "concept", "title": "Public role"}, {"id": "8d0649d3-b3d3-4c40-912a-069237f0370e", "type": "concept", "title": "Community consequence"}, {"id": "55539606-86e8-4742-bd8f-b729dad9c8e8", "type": "concept", "title": "Misconduct relevance"}, {"id": "a940fbd9-3198-4306-8709-547a56db629c", "type": "concept", "title": "Need to know"}], "description": "Students distinguish curiosity, spectacle, and genuine public relevance."}, {"id": "b1c4248a-3731-4b13-b378-887497ddbd93", "type": "subtopic", "title": "Consent and exposure", "children": [{"id": "ff544983-305f-4339-bc74-60acd51aa81d", "type": "concept", "title": "Minors"}, {"id": "1aea2f3b-f9e3-463c-9cf3-db356079724e", "type": "concept", "title": "Private citizens"}, {"id": "8887b47e-eb85-4233-a776-7114740dd892", "type": "conce