{"id": "345bc02b-701b-4a90-bc10-ae796b1d89b6", "type": "concept", "title": "Proportional sourcing"}, {"id": "1dc8e28b-d6c8-4299-8056-10520a09a39f", "type": "concept", "title": "Avoiding false balance"}, {"id": "aa144e54-2bea-4948-8296-269a7d736be4", "type": "concept", "title": "Contextual framing"}], "description": "Fairness means accurate representation of evidence, perspectives, and response opportunities."}, {"id": "1ecc42e7-399f-4289-84fd-887461ce0d82", "type": "subtopic", "title": "Transparency", "children": [{"id": "e74befa5-1eeb-4a67-98ff-c9007fc6a554", "type": "concept", "title": "How we know"}, {"id": "3d6dc4ab-f89c-4672-9b45-c5e41974edf1", "type": "concept", "title": "Method notes"}, {"id": "6186804b-82e7-4145-915f-1d205c08d9fe", "type": "concept", "title": "Corrections links"}, {"id": "abb4c103-2e94-43fa-a11a-fe26b3763aad", "type": "concept", "title": "Reporter disclosure"}], "description": "Students learn how explaining process can strengthen credibility without replacing verification."}]}, {"id": "5e572bde-60c0-4cfe-bbad-37e5415481ac", "type": "topic", "title": "Diversity, Representation, and Equity in Coverage", "description": "Builds ethical reporting habits around language, framing, stereotypes, power, and community context.", "children": [{"id": "d8075a56-cdbf-4b5c-9eb4-3299b96e90d2", "type": "subtopic", "title": "Inclusive sourcing", "children": [{"id": "bd0473ec-617a-4e35-b0e7-ffb67906f20e", "type": "concept", "title": "Source audits"}, {"id": "3f4a23d8-d80e-47e8-b47f-3f367643b0d2", "type": "concept", "title": "Community voices"}, {"id": "ce752138-e615-48e7-8ebc-ac8afb2451be", "type": "concept", "title": "Expert diversity"}, {"id": "ac4e6688-c7f6-4dd7-917c-4929497dbe38", "type": "concept", "title": "Language access"}], "description": "Coverage quality improves when source networks reflect affected communities and expertise."}, {"id": "9e597a23-e35e-4949-b856-bf1eabd167d7", "type": "subtopic", "title": "Framing and stereotypes", "children": [{"id":