tle": "Misinformation response", "children": [{"id": "dcd1f06d-61e8-471d-8951-8c20b46a3408", "type": "concept", "title": "Prebunking"}, {"id": "d65e57f6-d0ed-42c6-9c69-992bba40eb57", "type": "concept", "title": "Debunking"}, {"id": "05b01aa4-bdb9-4574-8d1c-5ad71a83c5b6", "type": "concept", "title": "Labeling uncertainty"}, {"id": "c11ccb55-2466-4016-ac9e-f7913db8cd6d", "type": "concept", "title": "Avoiding repetition traps"}], "description": "Students learn how to correct falsehoods without amplifying them irresponsibly."}, {"id": "d51e3642-12fd-4d66-9612-f20fb950b4c5", "type": "subtopic", "title": "AI and synthetic media", "children": [{"id": "af616a9c-230b-4d2f-8e1c-f85b1d646988", "type": "concept", "title": "Generative AI use"}, {"id": "010105b1-dc50-449b-a7d4-6b15020ddabc", "type": "concept", "title": "Deepfakes"}, {"id": "8800462c-97cb-4823-a6a9-d2ea4a49081e", "type": "concept", "title": "Automation disclosure"}, {"id": "d41f8415-7a7d-41a0-b33d-67aa92d6e2e5", "type": "concept", "title": "Bias testing"}], "description": "Journalists must evaluate disclosure, verification, authorship, and bias in AI-assisted work."}]}, {"id": "2703c71e-57da-4e24-8729-b611c3eaadb5", "type": "topic", "title": "Accountability, Corrections, Trust, and Audience Engagement", "description": "Treats correction, explanation, transparency, and audience trust as core ethical responsibilities.", "children": [{"id": "9019d3ad-46c2-45c5-940a-739038ebcf97", "type": "subtopic", "title": "Correction systems", "children": [{"id": "b17a6181-63f5-4614-b5ad-473864858eae", "type": "concept", "title": "Correction notes"}, {"id": "8228a0a4-3d01-4e7d-95e7-ee6e08835a02", "type": "concept", "title": "Clarifications"}, {"id": "3c63d9d8-028f-4f16-9f66-7c384726acac", "type": "concept", "title": "Update logs"}, {"id": "9e4b0ab6-5a13-4dc9-a63b-6ecefc3da5a4", "type": "concept", "title": "Social corrections"}], "description": "Accountability includes visible, timely, and specific correction practices."}, {"id": "0525dd2c-b673-4961-a493-2c8d5d03ea26", "type": "subtopic", "title": "Trust-building", "children": [{"id": "e411f674-1c29-4bd5-be0f-6b4fe8fa1e2f", "type": "concept", "title": "Process explanation"}, {"id": "1cdbff76-d357-4d8c-a3b3-10ee00fc6b9d", "type": "concept", "title": "Audience questions"}, {"id": "1c0ffabb-c1f6-4066-aebb-da1685551ac5", "type": "concept", "title": "Trust indicators"}, {"id": "93110b1b-1ced-4f17-8d9b-463a1735884a", "type": "concept", "title": "Community listening"}], "description": "Trust grows through consistent transparency, responsiveness, and evidence-centered communication."}, {"id": "dc25f1ce-29ec-4fbd-b8f2-3ea7e2c22819", "type": "subtopic", "title": "Public accountability", "children": [{"id": "94082aae-0450-4dd0-85df-9e691c74b78a", "type": "concept", "title": "Reader complaints"}, {"id": "57ad0869-e8ed-450a-8960-2478c19a22bd", "type": "concept", "title": "Ombuds models"}, {"id": "071c3683-666f-477e-b0fb-1d97ad995f3f", "type": "concept", "title": "Post-publication review"}, {"id": "0e03a9f4-50dc-441a-805d-f4bc043ca710", "type": "concept", "title": "Lessons learned"}], "description": "Students learn how journalists respond when coverage causes harm or misses the mark."}]}, {"id": "a204faf6-f8e6-4be3-ae47-221e36543d71", "type": "topic", "title": "Ethics Case Lab and Professional Standards Portfolio", "description": "Culminates in applied case analysis, newsroom policy writing, and a professional ethics decision portfolio.", "children": [{"id": "b1979e3e-f112-4b0a-9c88-604d8ffaee88", "type": "subtopic", "title": "Case analysis", "children": [{"id": "fa471f73-90bf-480e-a3d3-5c30d4082492", "type": "concept", "title": "Breaking news"}, {"id": "bdc5aea9-410f-45df-976b-1524bd16060c", "type": "concept", "title": "Anonymous sources"}, {"id": "265152c7-aeac-43c8-93d7-bd2c23b152a3", "type": "concept", "title": "Graphic images"}, {"id": "9a36669b-0a2a-4728-8dec-36210fe0d4d2", "type": "concept", "title": "AI-generated material"}], "description": "Students practice applying principles to real and simulated newsroom dilemmas."}, {"id": "7c77b7bb-cc1b-4f60-8f67-3b2e414155f9", "type": "subtopic", "title": "Policy drafting", "children": [{"id": "8b86a281-9489-4fae-afc7-de14803b4d0a", "type": "concept", "title": "Anonymous source policy"}, {"id": "cd2b83f5-d1b5-439f-80aa-367bae63deec", "type": "concept", "title": "Corrections policy"}, {"id": "71a69a47-43aa-428d-a3e0-d29763094d05", "type": "concept", "title": "AI policy"}, {"id": "cf860ae6-d103-4649-a3f1-770c1bf412a7", "type": "concept", "title": "Conflict policy"}], "description": "Writing policy forces students to translate values into usable newsroom rules."}, {"id": "879436c6-8bd5-40b6-ae46-81a45054acbd", "type": "subtopic", "title": "Ethics portfolio", "children": [{"id": "1de6aed2-d240-4307-84dd-f88680f6c0be", "type": "concept", "title": "Decision memo"}, {"id": "f53bb856-8513-4213-b793-1aab6e6f030e", "type": "concept", "title": "Case brief"}, {"id": "cd92e46c-39e9-483e-a0c0-9f24e2e916e7", "type": "concept", "title": "Standards statement"}, {"id": "6fa8f5a1-2ab6-4bcd-984f-d85bd8eaa6d3", "type": "concept", "title": "Reflection essay"}], "description": "The course culminates in artifacts students can use in internships and newsroom interviews."}]}], "dbBacked": true}$methjson$::jsonb,
