  data = $methjson${"slug": "media-ethics", "title": "Media Ethics", "description": "A journalism ethics course on ethical frameworks and newsroom decision-making, accuracy and truth-telling, independence and conflicts of interest, minimizing harm, sourcing and anonymity, privacy and consent, deception and hidden methods, objectivity and fairness, diversity in coverage, platform and AI ethics, and accountability, corrections, and audience trust.", "topics": [{"id": "c92f1cf0-a277-4310-8692-dd01eec3f481", "type": "topic", "title": "Ethical Frameworks and Newsroom Decision-Making", "description": "Introduces professional codes, moral reasoning, stakeholder analysis, and repeatable decision tools for journalism.", "children": [{"id": "bf804efb-ec35-47b7-a674-10696974c734", "type": "subtopic", "title": "Professional ethics codes", "children": [{"id": "5723d220-5882-48ae-ab97-aad8b0d6ff6a", "type": "concept", "title": "SPJ Code"}, {"id": "6e34a34b-60eb-4792-99b5-39f88f3d218b", "type": "concept", "title": "Reuters standards"}, {"id": "9898667e-62e8-4635-9694-215e7e29b4dd", "type": "concept", "title": "NPR handbook"}, {"id": "6f7b47b5-60c9-4ce5-ab69-1683f1e82e1d", "type": "concept", "title": "Newsroom policy comparison"}], "description": "Codes give journalists shared principles, but students must learn to apply them to messy situations."}, {"id": "4de140ad-d283-4eba-a4ca-e6a3e8bf9530", "type": "subtopic", "title": "Ethical reasoning models", "children": [{"id": "05f9bc89-135b-498e-9e4a-2ad8b33a3ba4", "type": "concept", "title": "Consequences"}, {"id": "84fcc29f-7db5-447c-bf32-bcc5b28a17bf", "type": "concept", "title": "Duties"}, {"id": "629b9e7c-6ea0-45d7-a8c1-ef27ac1f3fa1", "type": "concept", "title": "Virtues"}, {"id": "7d658b24-02c5-400e-a9e3-e018c615140d", "type": "concept", "title": "Stakeholder mapping"}], "description": "Decision frameworks slow down reactive judgment and make tradeoffs visible."}, {"id": "57ac3cb5-1e3d-4bc7-9e12-1a7f3cb0bb3b", "type": "subtopic", "title": "Newsroom deliberation", "children": [{"id": "98561265-b353-45d6-9131-a03adbe2fe36", "type": "concept", "title": "Decision memos"}, {"id": "d1e2b4ab-ab44-491b-b9cc-88eb1a6c2885", "type": "concept", "title": "Editor consultations"}, {"id": "abcdb237-258b-4961-aa45-506bc8270877", "type": "concept", "title": "Risk assessment"}, {"id": "7407b9fc-2f83-4f2e-a3dd-5badfd5364b4", "type": "concept", "title": "Public justification"}], "description": "Ethics becomes practical when students can argue, document, and defend decisions collaboratively."}]}, {"id": "c1a9029b-cc8d-4825-a4d1-eb2850c6be40", "type": "topic", "title": "Accuracy, Verification, and Truth-Telling", "description": "Centers truth-seeking through evidence, verification habits, context, uncertainty, and correction-resistant reporting.", "children": [{"id": "c376ca2c-1586-4cf0-9f88-f99f5205d6f5", "type": "subtopic", "title": "Verification discipline", "children": [{"id": "66c42fae-4afa-43c9-8d4c-7c67ac5d0bae", "type": "concept", "title": "Source triangulation"}, {"id": "dc57ca95-bb27-4969-86a8-0171b268f960", "type": "concept", "title": "Document checks"}, {"id": "4a937511-b9ea-4751-886f-6568bc16c7a0", "type": "concept", "title": "Quote verification"}, {"id": "748cb933-bf72-4677-861e-f48514ffecdd", "type": "concept", "title": "Chronology checks"}], "description": "Accuracy is an ethical obligation before it is a technical skill."}, {"id": "4cab105a-4400-443f-8aba-06470e97e9df", "type": "subtopic", "title": "Context and meaning", "children": [{"id": "6dcacb7d-bccd-4d58-ab09-66e001590f7e", "type": "concept", "title": "Statistical context"}, {"id": "279a53f2-6237-460b-a863-4fad838d94f7", "type": "concept", "title": "Historical background"}, {"id": "999d1cf9-3f90-42b0-be69-4b27f1c96cd4", "type": "concept", "title": "Missing caveats"}, {"id": "fb0049fc-5a48-4870-a3fa-0e8eff28f3b6", "type": "concept", "title": "Headline accuracy"}], "description": "Truth-telling includes context, proportion, and avoiding technically accurate but misleading frames."}, {"id": "6326f176-0dfb-4d36-9c06-97693c455f23", "type": "subtopic", "title": "Uncertainty and limits", "children": [{"id": "88164492-e721-444e-97ea-9aeccc6e5a21", "type": "concept", "title": "Attribution of uncertainty"}, {"id": "ac595631-326b-4d2d-a979-99a229429dd4", "type": "concept", "title": "Developing stories"}, {"id": "f33f7f6b-7440-486e-b862-cf50c7fb0eab", "type": "concept", "title": "Corrections risk"}, {"id": "41de8280-a27b-4ff2-a51a-91495e075eb8", "type": "concept", "title": "Avoiding overclaiming"}], "description": "Students learn to say what is known, unknown, contested, or still developing."}]}, {"id": "6e0b3b58-6bd4-4b51-a817-979db7df53b9", "type": "topic", "title": "Independence and Conflicts of Interest", "description": "Clarifies how journalists protect independence from political, financial, personal, source, and platform pressures.", "children": [{"id": "f8e35a44-43b7-42bc-8ac7-bc7c6e75f9cd", "type": "subtopic", "title": "Personal conflicts", "children": [{"id": "e292bd9b-df75-4c0c-9337-a58bd97958ef", "type": "concept", "title": "Family ties"}, {"id": "22b8b3e0-22db-4cc7-9885-986b2af08a07", "type": "concept", "title": "Political activity"}, {"id": "0857b0b7-a4ae-455d-9058-1962d9c679f9", "type": "concept", "title": "Gifts and favors"}, {"id": "9449f7c2-6665-4cfb-b8aa-d479fd7fe6de", "type": "concept", "title": "Outside employment"}], "description": "Students identify relationships and commitments that can compromise trust or judgment."}, {"id": "56e42b8a-0e9c-4057-8e5e-d142b2c771eb", "type": "subtopic", "title": "Institutional pressures", "children": [{"id": "1aec970f-3fb7-490b-92bc-54d26020b1ab", "type": "concept", "title": "Sponsored content"}, {"id": "ba600341-9daa-4b66-9028-04c444a61e3f", "type": "concept", "title": "Advertiser influence"}, {"id": "4620b9d1-5ea0-417b-9a11-d4aa4d813d5b", "type": "concept", "title": "Click pressure"}, {"id": "d67fbe59-f934-4a40-9241-474284147e2f", "type": "concept", "title": "Foundation funding"}], "description": "Newsroom ethics also involves owners, advertisers, funders, platforms, and audience incentives."}, {"id": "dc450e51-909e-49c4-b6d1-354e8e395937", "type": "subtopic", "title": "Independence practices", "children": [{"id": "60eddc68-ae61-4eaf-a3ea-67d3db5d7b1d", "type": "concept", "title": "Disclosure"}, {"id": "b946393a-6911-41dc-a508-9f77f0f7f804", "type": "concept", "title": "Recusal"}, {"id": "4ced168f-75d2-4b92-97ac-dcdec9ae5b5e", "type": "concept", "title": "Source boundaries"}, {"id": "45b90939-19d9-42d8-be5f-7f0ac5fe71a1", "type": "concept", "title": "Social media conduct"}], "description": "Clear boundaries help journalists maintain both actual and perceived independence."}]}, {"id": "f7f0b159-1ad6-4555-b8bd-416bd9e78a4e", "type": "topic", "title": "Minimizing Harm and Covering Vulnerable Communities", "description": "Balances public need to know with compassion, trauma awareness, dignity, and proportionality.", "children": [{"id": "9e74ccfa-aabe-47aa-87ff-3657cea0a04d", "type": "subtopic", "title": "Harm analysis", "children": [{"id": "9fc0b0b2-3e3a-4ce1-a14d-1c7640cb01d3", "type": "concept", "title": "Necessity"}, {"id": "c71196a0-1bcd-4f3a-b137-e81867106e0c", "type": "concept", "title": "Proportionality"}, {"id": "14ddcb47-00d7-4900-afc7-87a8d1463098", "type": "concept", "title": "Alternatives"}, {"id": "51696f6a-9031-48e0-8f41-535262f140fb", "type": "concept", "title": "After-publication impact"}], "description": "Students weigh public value against foreseeable harm to individuals and communities."}, {"id": "2e074553-d5fc-416e-959b-c1775c5802d1", "type": "subtopic", "title": "Trauma-informed reporting", "children": [{"id": "45314671-46fe-49c5-898f-a73e42f3ed97", "type": "concept", "title": "Informed consent"}, {"id": "e242ed81-2f3d-4f0c-bbea-d88d4b3ac650", "type": "concept", "title": "Interview pacing"}, {"id": "16cf08fb-55c4-4272-9a97-0a8d1ce15365", "type": "concept", "title": "Graphic detail choices"}, {"id": "cad27127-dd1d-4aeb-bb14-6eeb72983e5e", "type": "concept", "title": "Source control"}], "description": "Ethical interviewing requires care when sources have experienced grief, violence, or crisis."}, {"id": "564d5ce1-20b6-4985-bcdf-12c0c9aac3e7", "type": "subtopic", "title": "Dignity in coverage", "children": [{"id": "8c5c7109-95ce-4943-b5ee-45adc11201d3", "type": "concept", "title": "Photo ethics"}, {"id": "2b93930d-603d-448d-b38a-ae02f655dc64", "type": "concept", "title": "Victim identification"}, {"id": "e041d5e8-7868-4fa1-8901-1e878b6b0c4a", "type": "concept", "title": "Dehumanizing labels"}, {"id": "bba0c3fb-bb92-4de9-8f13-2573e71b7201", "type": "concept", "title": "Follow-up responsibility"}], "description": "Minimizing harm includes language, images, placement, and follow-up."}]}, {"id": "9bcd75e3-f3a8-4c69-a286-5b0db0df681a", "type": "topic", "title": "Sourcing, Anonymity, and Source Relationships", "description": "Examines when to grant anonymity, how to evaluate source motives, and how to avoid source capture.", "children": [{"id": "b0ba1526-1e79-459a-8373-1257c816d0f8", "type": "subtopic", "title": "Source evaluation", "children": [{"id": "1ce966ee-b32d-4c73-9719-802babdf97d8", "type": "concept", "title": "Motive"}, {"id": "6c37cd42-f8c6-49a9-9869-d684c776a8a8", "type": "concept", "title": "Proximity"}, {"id": "a77c3063-0391-4105-b914-743b53f88282", "type": "concept", "title": "Expertise"}, {"id": "cbf265bc-3210-4c25-ad5e-600d88039978", "type": "concept", "title": "Power position"}], "description": "Students examine who knows what, how they know it, and what they want from publication."}, {"id": "68931e69-b4a7-4646-949d-d1528af7b5b2", "type": "subtopic", "title": "Anonymous sourcing", "children": [{"id": "8661eb1a-9874-4f2b-ae56-2b6a661642de", "type": "concept", "title": "Public interest"}, {"id": "bfbe392b-bb05-40e8-83bc-8d8b5c898167", "type": "concept", "title": "Risk to source"}, {"id": "de7e0dc2-f094-46fb-8027-d9f3a9244576", "type": "concept", "title": 